-- ============================================
-- AIoT Device Management Platform Schema
-- PostgreSQL 15+
-- Generated by Claude Code Team
-- ============================================

-- ============================================
-- 0. DICTIONARY: Device Types
-- ============================================
CREATE TABLE IF NOT EXISTS dict_device_type (
    id              SMALLSERIAL PRIMARY KEY,
    name            VARCHAR(32) NOT NULL UNIQUE,
    description     VARCHAR(128)
);

INSERT INTO dict_device_type (name, description) VALUES
