    ('NVR', 'Network Video Recorder'),
    ('DVR', 'Digital Video Recorder'),
    ('Encoder', 'Video Encoder'),
    ('Decoder', 'Video Decoder'),
    ('Storage', 'Storage Device');

-- ============================================
-- 1. ORGANIZATIONS (Hierarchical)
-- ============================================
CREATE TABLE IF NOT EXISTS org (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(128) NOT NULL,
    code            VARCHAR(32) UNIQUE,
    parent_id       BIGINT REFERENCES org(id) ON DELETE SET NULL,
    level           SMALLINT NOT NULL DEFAULT 0,
    sort_order      SMALLINT NOT NULL DEFAULT 0,
    status          SMALLINT NOT NULL DEFAULT 1,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(parent_id, name)
);

CREATE INDEX idx_org_parent ON org(parent_id);
CREATE INDEX idx_org_level ON org(level);
CREATE INDEX idx_org_status ON org(status);
CREATE INDEX idx_org_code ON org(code);

-- ============================================
-- 2. ROLES
-- ============================================
CREATE TABLE IF NOT EXISTS role (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(64) NOT NULL,
    code            VARCHAR(32) NOT NULL UNIQUE,
    description     VARCHAR(256),
    permissions     JSONB NOT NULL DEFAULT '[]',
    status          SMALLINT NOT NULL DEFAULT 1,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_role_code ON role(code);
CREATE INDEX idx_role_status ON role(status);

-- ============================================
-- 3. USERS
-- ============================================
CREATE TABLE IF NOT EXISTS users (
    id              BIGSERIAL PRIMARY KEY,
    username        VARCHAR(64) NOT NULL UNIQUE,
    password_hash   VARCHAR(256) NOT NULL,
    phone           VARCHAR(32),
    email           VARCHAR(128),
    gender          SMALLINT DEFAULT 0 CHECK (gender IN (0, 1, 2)),
    avatar          VARCHAR(512),
    org_id          BIGINT REFERENCES org(id) ON DELETE SET NULL,
    role_id         BIGINT REFERENCES role(id) ON DELETE SET NULL,
    status          SMALLINT NOT NULL DEFAULT 1,
    last_login      TIMESTAMPTZ,
    deleted_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_users_org ON users(org_id);
CREATE INDEX idx_users_role ON users(role_id);
CREATE INDEX idx_users_status ON users(status);
CREATE INDEX idx_users_username ON users(username);
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_users_deleted ON users(deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_users_org_role ON users(org_id, role_id);

-- ============================================
-- 4. DEVICE GROUPS (Hierarchical)
-- ============================================
CREATE TABLE IF NOT EXISTS device_group (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(128) NOT NULL,
    parent_id       BIGINT REFERENCES device_group(id) ON DELETE CASCADE,
    sort_order      SMALLINT NOT NULL DEFAULT 0,
    deleted_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(parent_id, name)
);

CREATE INDEX idx_device_group_parent ON device_group(parent_id);
CREATE INDEX idx_device_group_deleted ON device_group(deleted_at) WHERE deleted_at IS NOT NULL;

-- ============================================
-- 5. DEVICES
-- ============================================
CREATE TABLE IF NOT EXISTS device (
    id                      BIGSERIAL PRIMARY KEY,
    device_name             VARCHAR(128) NOT NULL,
    device_sn               VARCHAR(128),
    device_ip               VARCHAR(64),
    device_port             INTEGER,
    device_type             SMALLINT NOT NULL REFERENCES dict_device_type(id),
    firmware_version        VARCHAR(64),
    department              VARCHAR(128),
    product_type            VARCHAR(64),
    cpu_cores               SMALLINT DEFAULT 0,
    cpu_usage               DECIMAL(5,2) DEFAULT 0,
    memory_size             BIGINT DEFAULT 0,
    memory_usage            BIGINT DEFAULT 0,
    disk_size               BIGINT DEFAULT 0,
    disk_usage              BIGINT DEFAULT 0,
    video_source_count      SMALLINT DEFAULT 0,
    online_status           SMALLINT NOT NULL DEFAULT 0 CHECK (online_status IN (0, 1, 2)),
    last_heartbeat_at      TIMESTAMPTZ,
    auth_status             SMALLINT DEFAULT 0,
    auth_expire_time        TIMESTAMPTZ,
    region_id               BIGINT REFERENCES region(id) ON DELETE SET NULL,
    org_id                  BIGINT REFERENCES org(id) ON DELETE SET NULL,
    deleted_at              TIMESTAMPTZ,
    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_device_name ON device(device_name);
CREATE INDEX idx_device_ip ON device(device_ip);
CREATE INDEX idx_device_type ON device(device_type);
CREATE INDEX idx_device_online ON device(online_status);
CREATE INDEX idx_device_department ON device(department);
CREATE INDEX idx_device_region ON device(region_id);
CREATE INDEX idx_device_org ON device(org_id);
CREATE INDEX idx_device_deleted ON device(deleted_at) WHERE deleted_at IS NOT NULL;
CREATE INDEX idx_device_online_heartbeat ON device(online_status, last_heartbeat_at) WHERE online_status = 1;
CREATE INDEX idx_device_org_online ON device(org_id, online_status);

-- ============================================
-- 6. DEVICE-GROUP MEMBERSHIP (Junction)
-- ============================================
CREATE TABLE IF NOT EXISTS device_group_member (
    device_id       BIGINT NOT NULL REFERENCES device(id) ON DELETE CASCADE,
    group_id        BIGINT NOT NULL REFERENCES device_group(id) ON DELETE CASCADE,
    PRIMARY KEY (device_id, group_id)
);

CREATE INDEX idx_device_group_member_device ON device_group_member(device_id);
CREATE INDEX idx_device_group_member_group ON device_group_member(group_id);

-- ============================================
-- 7. REGIONS (Hierarchical)
-- ============================================
CREATE TABLE IF NOT EXISTS region (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(128) NOT NULL,
    code            VARCHAR(32) NOT NULL UNIQUE,
    parent_id       BIGINT REFERENCES region(id) ON DELETE CASCADE,
    deleted_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE(parent_id, name)
);

CREATE INDEX idx_region_code ON region(code);
CREATE INDEX idx_region_parent ON region(parent_id);
CREATE INDEX idx_region_deleted ON region(deleted_at) WHERE deleted_at IS NOT NULL;

-- ============================================
-- 8. DATA SOURCES
-- ============================================
CREATE TABLE IF NOT EXISTS data_source (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(128) NOT NULL,
    type            VARCHAR(32) NOT NULL,
    config          JSONB NOT NULL DEFAULT '{}',
    status          SMALLINT NOT NULL DEFAULT 1,
    deleted_at      TIMESTAMPTZ,
