-- ============================================
-- AUTOMATED PARTITION CREATION FUNCTION
-- ============================================
CREATE OR REPLACE FUNCTION make_partition_if_missing(
    table_name TEXT,
    partition_date DATE
) RETURNS VOID AS $$
DECLARE
    partition_suffix TEXT;
    start_date DATE;
    end_date DATE;
    partition_exists BOOLEAN;
BEGIN
    partition_suffix := to_char(partition_date, 'YYYY_MM');
    start_date := date_trunc('month', partition_date);
    end_date := start_date + interval '1 month';

    EXECUTE format(
        'SELECT EXISTS (SELECT 1 FROM pg_class WHERE relname = $1)',
        table_name || '_' || partition_suffix
    ) INTO partition_exists;

    IF NOT partition_exists THEN
        EXECUTE format(
            'CREATE TABLE IF NOT EXISTS %I PARTITION OF %I FOR VALUES FROM (%L) TO (%L)',
            table_name || '_' || partition_suffix,
            table_name,
            start_date,
            end_date
        );
        RAISE NOTICE 'Created partition: %', table_name || '_' || partition_suffix;
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Function to ensure partitions exist for the next N months
CREATE OR REPLACE FUNCTION ensure_future_partitions(
    table_name TEXT,
    months_ahead INTEGER DEFAULT 3
) RETURNS VOID AS $$
DECLARE
    i INTEGER;
    target_date DATE;
BEGIN
    FOR i IN 0..months_ahead LOOP
        target_date := date_trunc('month', CURRENT_DATE) + (i || ' months')::interval;
        PERFORM make_partition_if_missing(table_name, target_date);
    END LOOP;
END;
$$ LANGUAGE plpgsql;

-- ============================================
-- TRIGGER: Auto-update updated_at
-- ============================================
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply to all tables with updated_at
CREATE TRIGGER tr_org_updated BEFORE UPDATE ON org FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_users_updated BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_role_updated BEFORE UPDATE ON role FOR EACH ROW EXECUTE FUNCTION update_updated_at();
