CREATE TRIGGER tr_algorithm_updated BEFORE UPDATE ON algorithm FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_algorithm_event_updated BEFORE UPDATE ON algorithm_event FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_algorithm_service_updated BEFORE UPDATE ON algorithm_service FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_linkage_rule_updated BEFORE UPDATE ON linkage_rule FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_menu_updated BEFORE UPDATE ON menu FOR EACH ROW EXECUTE FUNCTION update_updated_at();
CREATE TRIGGER tr_resource_updated BEFORE UPDATE ON resource FOR EACH ROW EXECUTE FUNCTION update_updated_at();
