-- ============================================
-- VIEWS: For common queries
-- ============================================

-- Device with organization and region info
-- Note: memory_size and disk_size are stored in bytes (BIGINT).
-- API responses return human-readable strings (e.g., "16G", "256G").
CREATE OR REPLACE VIEW v_device_details AS
SELECT
    d.id,
    d.device_name,
    d.device_sn,
    d.device_ip,
    d.device_port,
    d.device_type,
    dt.name AS device_type_name,
    d.firmware_version,
    d.department,
    d.product_type,
    d.cpu_cores,
    d.cpu_usage,
    d.memory_size,
    d.memory_usage,
    d.disk_size,
    d.disk_usage,
    d.video_source_count,
    d.online_status,
    d.last_heartbeat_at,
    d.auth_status,
    d.auth_expire_time,
    d.region_id,
    r.name AS region_name,
    d.org_id,
    o.name AS org_name,
    d.deleted_at,
    d.created_at,
    d.updated_at,
    CASE
        WHEN d.memory_size >= 1073741824 THEN (d.memory_size / 1073741824.0)::TEXT || 'G'
        WHEN d.memory_size >= 1048576 THEN (d.memory_size / 1048576.0)::TEXT || 'M'
        WHEN d.memory_size >= 1024 THEN (d.memory_size / 1024.0)::TEXT || 'K'
        ELSE d.memory_size::TEXT
    END AS memory_size_fmt,
    CASE
        WHEN d.disk_size >= 1073741824 THEN (d.disk_size / 1073741824.0)::TEXT || 'G'
        WHEN d.disk_size >= 1048576 THEN (d.disk_size / 1048576.0)::TEXT || 'M'
        WHEN d.disk_size >= 1024 THEN (d.disk_size / 1024.0)::TEXT || 'K'
        ELSE d.disk_size::TEXT
    END AS disk_size_fmt
FROM device d
LEFT JOIN dict_device_type dt ON d.device_type = dt.id
LEFT JOIN region r ON d.region_id = r.id
LEFT JOIN org o ON d.org_id = o.id;

-- User with role and org names (excluding password_hash)
CREATE OR REPLACE VIEW v_user_details AS
SELECT
    u.id,
    u.username,
    u.phone,
    u.email,
    u.gender,
    u.avatar,
    u.org_id,
    o.name AS org_name,
    u.role_id,
    r.name AS role_name,
    r.code AS role_code,
    u.status,
    u.last_login,
    u.deleted_at,
    u.created_at,
    u.updated_at
FROM users u
LEFT JOIN role r ON u.role_id = r.id
LEFT JOIN org o ON u.org_id = o.id;

